panels.script:
const ngu = window.ngu;
const line = panel.querySelector('#tk-line');
const need = panel.querySelector('#tk-need');
function paint(state){
  if(!state){ line.textContent = '还没有票：用 ticket_open 开一张'; need.textContent=''; return; }
  line.textContent = '活票 ' + state.open + ' · 在跑 ' + state.running + ' · 待验收 ' + state.delivered + ' · 卡住 ' + state.stuck + ' · 已关 ' + state.closed;
  need.textContent = (state.attention && state.attention.length) ? ('要处理：' + state.attention.join(' ')) : '';
}
function scan(text){
  if(typeof text !== 'string') return;
  const m = text.match(/<!--ticket-state (\{[^}]*\})-->/);
  if(!m) return;
  try { paint(JSON.parse(m[1])); } catch (e) {}
}
if (ngu && typeof ngu.on === 'function') {
  ngu.on('tool_end', function(ev){ scan(ev && ev.result); });
}
line.title = '票看板：来自主代理每次 ticket_* 调用的结果标记';
